  "integrated-seabass-business_250": { "th": "800–1,000 กรัม", "en": "800–1,000 grams" },
  "integrated-seabass-business_251": { "th": "อัตรารอด", "en": "Survival rate" },
  "integrated-seabass-business_252": { "th": "80–85%", "en": "80–85%" },
  "integrated-seabass-business_253": { "th": "90%", "en": "90%" },
  "integrated-seabass-business_254": { "th": "FCR", "en": "FCR" },
